// Left-pads a non-negative integer with zeros to the given width.
fn zero_pad(n int, width int) String
    let digits = f"{n}"
    "0".repeat(width - digits.length()) + digits

// Decimal digits of a non-negative whole-valued float. Values past the int
// range are split into 18-digit chunks; their low digits are approximate
// because a float that large has no more precision than that.
fn whole_str(w float) String
    if w < 1000000000000000000.0
        return f"{w as int}"
    let hi = floor(w / 1000000000000000000.0)
    let lo = clamp(w - hi * 1000000000000000000.0, 0.0, 999999999999999999.0)
    whole_str(hi) + zero_pad(lo as int, 18)

// Formats a value with exactly six digits after the decimal point.
fn fmt6(x float) String
    let a = abs(x)
    let base = floor(a)
    var cents = round((a - base) * 1000000.0) as int
    var whole = base
    if cents == 1000000
        cents = 0
        whole = base + 1.0
    let sign = if x < 0.0 and (whole > 0.0 or cents > 0): "-" else: ""
    f"{sign}{whole_str(whole)}.{zero_pad(cents, 6)}"

